import{Lt as e,Vt as t,Z as n,_t as r,bt as i,vt as a}from"./chunks/framework.CsLlEPF4.js";var o=JSON.parse(`{"title":"CSL 中文文档","description":"","frontmatter":{"title":"CSL 中文文档","date":"2022-08-01T16:23:04.000Z","updated":"2023-07-22T20:39:20.000Z"},"headers":[],"relativePath":"csl-dev-guide/index.md","filePath":"wiki/csl-dev-guide/index.md"}`),s={name:`csl-dev-guide/index.md`};function c(n,o,s,c,l,u){let d=t(`NolebaseGitContributors`),f=t(`NolebaseGitChangelog`);return e(),r(`div`,null,[o[0]||=a(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /csl-dev-guideindex.md for this page in Markdown format</div><h1 id="csl-中文文档" tabindex="-1">CSL 中文文档 <a class="header-anchor" href="#csl-中文文档" aria-label="Permalink to “CSL 中文文档”">​</a></h1><p>此文档是对 <a href="https://docs.citationstyles.org/en/stable/primer.html" target="_blank" rel="noreferrer">CSL 英文文档</a> 的翻译。它最初由 <a href="https://github.com/ZMAlt" target="_blank" rel="noreferrer">ZMAlt</a> 维护并发布于 <a href="https://csl-chinese.readthedocs.io/en/latest/" target="_blank" rel="noreferrer">CSL-chinese documentation</a>，后来 <a href="https://github.com/zotero-chinese" target="_blank" rel="noreferrer">Zotero Chinese</a> 社区接管了维护工作。</p><p>出版物对参考文献的一系列引注规则构成了其引注样式，CSL 旨在提供一种计算机可读的语言来描述这些规则，从而在文献管理软件（如 <a href="https://www.zotero.org/" target="_blank" rel="noreferrer">Zotero</a>、<a href="https://www.mendeley.com/" target="_blank" rel="noreferrer">Mendeley</a>、<a href="https://www.papersapp.com/" target="_blank" rel="noreferrer">Papers</a>）中自动生成引注。虽然 CSL 已经涵盖多个语言地区的数千种样式，但现实的需求是多样的，如果你没能在 CSL 样式仓库（<a href="https://www.zotero.org/styles" target="_blank" rel="noreferrer">官方仓库</a> 或 <a href="/styles/">中文社区仓库</a>）中找到合适的样式，而且 <a href="/user-guide/citation-styles#请求新样式">申请新样式</a> 的周期太长，那么你可以参考本文档着手修改或创建自己的样式。</p>`,4),i(d),i(f)])}var l=n(s,[[`render`,c]]);export{o as __pageData,l as default};